const status = msg.payload;
const txtOn = env.get("texto_on");
const txtOff = env.get("texto_off");

// 1. Resolve a mensagem
let mensagem = (status === 'on') ? txtOn : txtOff;

// Se vier de uma propriedade da msg (como o payload do Google)
if (mensagem && typeof mensagem === 'string') {
    if (mensagem.startsWith('msg.')) {
        mensagem = RED.util.getMessageProperty(msg, mensagem.split('.')[1]);
    } else if (msg[mensagem]) {
        mensagem = msg[mensagem];
    }
}

// Fallback para o payload direto se nada foi resolvido
const textoFinal = mensagem || (typeof msg.payload === 'string' ? msg.payload : "Alerta");

// 2. Resolve os destinos
const destinosRaw = [
    env.get("notifica_app_1"),
    env.get("notifica_app_2"),
    env.get("notifica_app_3"),
    env.get("notifica_app_4")
];

// Filtra destinos vazios ou não resolvidos
const destinosValidos = destinosRaw.filter(d => {
    if (!d || typeof d !== 'string') return false;
    const limpo = d.trim();
    // IMPORTANTE: Só deixa passar se o valor NÃO for o nome da variável de ambiente
    return limpo !== "" && 
           limpo !== "service_app_notify_1" && 
           limpo !== "service_app_notify_2" &&
           limpo !== "service_app_notify_3" &&
           limpo !== "service_app_notify_4";
});

if (destinosValidos.length === 0) return null;

// 3. Monta as mensagens
const msgs = destinosValidos.map(d => {
    let servico = d.trim();
    if (!servico.includes('.')) servico = 'notify.' + servico;

    return {
        ...msg,
        service: servico,
        hadata: { "message": textoFinal }
    };
});

return [msgs];

const status = msg.payload;
const txtOn = env.get("texto_falado_on");
const txtOff = env.get("texto_falado_off");

// Se o payload já for um texto pronto, usa diretamente
if (typeof msg.payload === "string") {
    const textoDireto = msg.payload.trim();
    if (textoDireto !== "" && textoDireto !== "on" && textoDireto !== "off") {
        return [msg, msg];
    }
}

// Resolve o texto (fixo ou vindo de msg.prop)
let texto = (status === 'on') ? txtOn : txtOff;

if (texto && typeof texto === 'string') {
    if (texto.startsWith('msg.')) {
        texto = RED.util.getMessageProperty(msg, texto.split('.').slice(1).join('.'));
    } else if (msg[texto] !== undefined) {
        texto = msg[texto];
    }
}

msg.payload = texto || "Alerta";

// Saída 1: Voz | Saída 2: Notificação App
return [msg, msg];
